/*
 * run.c - checkpointed, OpenMP-parallel sweep over all Bruhat pairs of S_n.
 *
 * Symmetry.  The Klein four-group generated by
 *     alpha: (u, w) -> (w0 w, w0 u)    (same polynomial D)
 *     beta : (u, w) -> (w0 u w0, w0 w w0)  (y_k -> y_{n-1-k})
 * preserves SCNP.  Every orbit meets
 *     S = { (u, w) : idx(u) <= idx(w0 u w0), l(u) + l(w) <= N },
 * so only bottoms u that are conjugation-canonical with 2 l(u) <= N are swept,
 * and only up to l(w) <= N - l(u).  A processed pair p is counted, and its
 * whole orbit written out, iff p is the smallest member of orbit(p) ∩ S.
 *
 * Checkpointing.  Bottoms are dealt round-robin into nchunks chunks.  A chunk
 * writes DIR/chunks/NNNNN.txt (failing pairs) and then DIR/chunks/NNNNN.stat;
 * both go through a .tmp file + fsync + rename, and a chunk counts as done
 * iff its .stat exists.  Killing the program loses at most the chunks in
 * flight; rerunning the same command resumes.
 */
#include "scnp.h"

#include <errno.h>
#include <fcntl.h>
#include <omp.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <zlib.h>

typedef struct {
    uint32_t u, w;
} pair_t;

enum { LIST_NONE, LIST_REPS, LIST_ALL };

typedef struct {
    const tables_t *T;
    int sym, list;
    uint64_t pairs[MAXL], fails[MAXL], fails_id[MAXL];
    FILE *out;     /* plain text output, or */
    gzFile gz;     /* gzip output            */
    char *buf;
    size_t blen;
    uint8_t *badw; /* badw[w] = 1: some u <= w with D_u^w not SCNP */
} cctx_t;

#define OUTBUF (1u << 20)

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig)
{
    (void)sig;
    g_stop = 1;
}

static double now(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + 1e-9 * ts.tv_nsec;
}

static void flush_buf(cctx_t *c)
{
    if (!c->blen)
        return;
    if (c->gz ? gzwrite(c->gz, c->buf, (unsigned)c->blen) != (int)c->blen
              : fwrite(c->buf, 1, c->blen, c->out) != c->blen) {
        perror("write");
        exit(1);
    }
    c->blen = 0;
}

static void emit(cctx_t *c, pair_t p)
{
    const tables_t *T = c->T;
    int n = T->n, d = T->len[p.w] - T->len[p.u];
    if (c->blen + 2 * n + 8 > OUTBUF)
        flush_buf(c);
    char *s = c->buf + c->blen;
    format_perm(PERM(T, p.u), n, s);
    s[n] = ' ';
    format_perm(PERM(T, p.w), n, s + n + 1);
    s += 2 * n + 1;
    *s++ = ' ';
    if (d >= 10)
        *s++ = (char)('0' + d / 10);
    *s++ = (char)('0' + d % 10);
    *s++ = '\n';
    c->blen = (size_t)(s - c->buf);
}

static int orbit(const tables_t *T, pair_t p, pair_t o[4])
{
    pair_t c[4] = {p,
                   {T->lw0[p.w], T->lw0[p.u]},
                   {T->cw0[p.u], T->cw0[p.w]},
                   {T->rw0[p.w], T->rw0[p.u]}};
    int k = 0;
    for (int i = 0; i < 4; i++) {
        int dup = 0;
        for (int j = 0; j < k; j++)
            dup |= o[j].u == c[i].u && o[j].w == c[i].w;
        if (!dup)
            o[k++] = c[i];
    }
    return k;
}

static int in_S(const tables_t *T, pair_t q)
{
    return T->cw0[q.u] >= q.u && T->len[q.u] + T->len[q.w] <= T->N;
}

static int pair_less(pair_t a, pair_t b)
{
    return a.u < b.u || (a.u == b.u && a.w < b.w);
}

static void handle_general(cctx_t *c, pair_t p, int d, int ok)
{
    pair_t o[4];
    int k = orbit(c->T, p, o);
    for (int i = 0; i < k; i++)
        if (in_S(c->T, o[i]) && pair_less(o[i], p))
            return; /* another member of the orbit is responsible */
    c->pairs[d] += (uint64_t)k;
    if (!ok) {
        c->fails[d] += (uint64_t)k;
        for (int i = 0; i < k; i++) {
            c->fails_id[d] += o[i].u == c->T->id;
            c->badw[o[i].w] = 1;
            if (c->list == LIST_ALL || (c->list == LIST_REPS && i == 0))
                emit(c, o[i]);
        }
    }
}

static void on_level(void *vctx, uint32_t u, int d, const uint32_t *node,
                     const uint8_t *F, const vec_t *H, uint32_t cnt)
{
    (void)H;
    cctx_t *c = vctx;
    const tables_t *T = c->T;
    if (!c->sym) {
        c->pairs[d] += cnt;
        for (uint32_t s = 0; s < cnt; s++)
            if (!F[s]) {
                c->fails[d]++;
                c->fails_id[d] += u == T->id;
                c->badw[node[s]] = 1;
                if (c->list != LIST_NONE)
                    emit(c, (pair_t){u, node[s]});
            }
        return;
    }
    if (2 * T->len[u] + d < T->N && T->cw0[u] != u) {
        /* generic case: the orbit has 4 distinct members, only p lies in S,
         * and none has bottom id (that would force u = id or w = w0).    */
        c->pairs[d] += 4ull * cnt;
        for (uint32_t s = 0; s < cnt; s++)
            if (!F[s]) {
                pair_t o[4];
                orbit(T, (pair_t){u, node[s]}, o);
                c->fails[d] += 4;
                for (int i = 0; i < 4; i++)
                    c->badw[o[i].w] = 1;
                if (c->list != LIST_NONE)
                    for (int i = 0; i < (c->list == LIST_ALL ? 4 : 1); i++)
                        emit(c, o[i]);
            }
        return;
    }
    for (uint32_t s = 0; s < cnt; s++)
        handle_general(c, (pair_t){u, node[s]}, d, F[s]);
}

/* ---------------------------------------------------------------- files */

int file_exists(const char *path)
{
    struct stat st;
    return stat(path, &st) == 0;
}

void mkdir_p(const char *path)
{
    if (mkdir(path, 0777) && errno != EEXIST) {
        fprintf(stderr, "cannot create %s: %s\n", path, strerror(errno));
        exit(1);
    }
}

/* tmp has been closed; make it durable and give it its final name */
void commit_file(const char *tmp, const char *final)
{
    int fd = open(tmp, O_RDONLY);
    if (fd < 0 || fsync(fd) || close(fd) || rename(tmp, final)) {
        fprintf(stderr, "cannot commit %s: %s\n", final, strerror(errno));
        exit(1);
    }
}

static void write_stat(const char *dir, int chunk, const cctx_t *c, int N,
                       uint64_t pushes, double secs)
{
    char tmp[4096], fin[4096];
    snprintf(tmp, sizeof tmp, "%s/chunks/%05d.stat.tmp", dir, chunk);
    snprintf(fin, sizeof fin, "%s/chunks/%05d.stat", dir, chunk);
    FILE *f = fopen(tmp, "w");
    if (!f) {
        perror(tmp);
        exit(1);
    }
    fprintf(f, "chunk %d\npushes %llu\nseconds %.3f\n", chunk,
            (unsigned long long)pushes, secs);
    for (int d = 0; d <= N; d++)
        if (c->pairs[d])
            fprintf(f, "L %d %llu %llu %llu\n", d,
                    (unsigned long long)c->pairs[d],
                    (unsigned long long)c->fails[d],
                    (unsigned long long)c->fails_id[d]);
    if (fclose(f)) {
        perror(tmp);
        exit(1);
    }
    commit_file(tmp, fin);
}

/* DIR/badw.bin: bit w set iff some u <= w has D_u^w not SCNP.  It is
 * rewritten (atomically) before each chunk's .stat, so it always covers
 * every completed chunk; bits only ever record genuine failures.        */
int load_badw(const char *dir, uint8_t *bits, size_t nbytes)
{
    char path[4096];
    snprintf(path, sizeof path, "%s/badw.bin", dir);
    FILE *f = fopen(path, "rb");
    if (!f)
        return 0;
    size_t got = fread(bits, 1, nbytes, f);
    int extra = fgetc(f) != EOF;
    fclose(f);
    if (got != nbytes || extra) {
        fprintf(stderr, "%s has the wrong size\n", path);
        exit(1);
    }
    return 1;
}

static void save_badw(const char *dir, const uint8_t *bits, size_t nbytes)
{
    char tmp[4096], fin[4096];
    snprintf(tmp, sizeof tmp, "%s/badw.bin.tmp", dir);
    snprintf(fin, sizeof fin, "%s/badw.bin", dir);
    FILE *f = fopen(tmp, "wb");
    if (!f || fwrite(bits, 1, nbytes, f) != nbytes || fclose(f)) {
        perror(tmp);
        exit(1);
    }
    commit_file(tmp, fin);
}

static const char *list_name[] = {"none", "reps", "all"};

static void check_config(const char *dir, int n, int sym, int nchunks, int maxlen,
                         int list, int gz)
{
    char path[4096], want[256], have[256] = "";
    snprintf(path, sizeof path, "%s/config", dir);
    snprintf(want, sizeof want,
             "scnp-sweep v1 n=%d sym=%d chunks=%d maxlen=%d list=%s gzip=%d\n",
             n, sym, nchunks, maxlen, list_name[list], gz);
    FILE *f = fopen(path, "r");
    if (f) {
        if (!fgets(have, sizeof have, f))
            have[0] = 0;
        fclose(f);
        if (strcmp(have, want)) {
            fprintf(stderr,
                    "%s was created with different parameters:\n  %s"
                    "requested:\n  %s", path, have, want);
            exit(1);
        }
        return;
    }
    f = fopen(path, "w");
    if (!f || fputs(want, f) < 0 || fclose(f)) {
        perror(path);
        exit(1);
    }
}

/* -------------------------------------------------------------- summary */

int run_summary(const char *dir)
{
    char path[4096];
    snprintf(path, sizeof path, "%s/config", dir);
    FILE *f = fopen(path, "r");
    int n = 0, sym = 0, nchunks = 0, maxlen = 0, gz = 0;
    char list[16] = "";
    if (!f || fscanf(f, "scnp-sweep v1 n=%d sym=%d chunks=%d maxlen=%d list=%15s gzip=%d",
                     &n, &sym, &nchunks, &maxlen, list, &gz) != 6) {
        fprintf(stderr, "%s: missing or unreadable config\n", dir);
        return 1;
    }
    fclose(f);
    int N = n * (n - 1) / 2;
    uint64_t P[MAXL] = {0}, Fl[MAXL] = {0}, Fi[MAXL] = {0}, pushes = 0;
    double secs = 0;
    int done = 0;
    for (int c = 0; c < nchunks; c++) {
        snprintf(path, sizeof path, "%s/chunks/%05d.stat", dir, c);
        f = fopen(path, "r");
        if (!f)
            continue;
        done++;
        char line[256];
        while (fgets(line, sizeof line, f)) {
            int d;
            unsigned long long a, b, e;
            double s;
            if (sscanf(line, "L %d %llu %llu %llu", &d, &a, &b, &e) == 4 &&
                d >= 0 && d < MAXL) {
                P[d] += a;
                Fl[d] += b;
                Fi[d] += e;
            } else if (sscanf(line, "pushes %llu", &a) == 1)
                pushes += a;
            else if (sscanf(line, "seconds %lf", &s) == 1)
                secs += s;
        }
        fclose(f);
    }
    uint32_t np = 1;
    for (int i = 2; i <= n; i++)
        np *= (uint32_t)i;
    size_t nbytes = (np + 7) / 8;
    uint8_t *bits = calloc(nbytes, 1);
    int have_bits = load_badw(dir, bits, nbytes);
    uint64_t nbad = 0;
    for (size_t i = 0; i < nbytes; i++)
        nbad += (uint64_t)__builtin_popcount(bits[i]);
    free(bits);
    snprintf(path, sizeof path, "%s/summary.txt", dir);
    FILE *out = fopen(path, "w");
    FILE *dst[2] = {stdout, out};
    uint64_t tp = 0, tf = 0, ti = 0;
    for (int d = 0; d <= N; d++) {
        tp += P[d];
        tf += Fl[d];
        ti += Fi[d];
    }
    for (int k = 0; k < 2; k++) {
        FILE *o = dst[k];
        if (!o)
            continue;
        fprintf(o, "# SCNP sweep of S_%d  (%s)\n", n,
                sym ? "symmetry-reduced" : "no symmetry reduction");
        fprintf(o, "# chunks done: %d / %d%s\n", done, nchunks,
                done == nchunks ? "" : "   ** INCOMPLETE: counts are partial **");
        if (maxlen < N)
            fprintf(o, "# interval lengths restricted to <= %d\n", maxlen);
        fprintf(o, "# failing pairs listed: %s%s\n", list,
                !strcmp(list, "reps") ? " (one per symmetry orbit, see README)" : "");
        fprintf(o, "# cpu seconds in chunks: %.1f, DP edge relaxations: %llu\n",
                secs, (unsigned long long)pushes);
        fprintf(o, "# %4s %16s %16s %10s %12s\n", "len", "pairs u<=w",
                "SCNP fails", "fraction", "fails u=id");
        for (int d = 0; d <= N; d++)
            if (P[d])
                fprintf(o, "  %4d %16llu %16llu %10.6f %12llu\n", d,
                        (unsigned long long)P[d], (unsigned long long)Fl[d],
                        (double)Fl[d] / (double)P[d], (unsigned long long)Fi[d]);
        fprintf(o, "  %4s %16llu %16llu %10.6f %12llu\n", "all",
                (unsigned long long)tp, (unsigned long long)tf,
                tp ? (double)tf / (double)tp : 0.0, (unsigned long long)ti);
        if (have_bits)
            fprintf(o, "# w in S_%d admitting some u with D_u^w not SCNP: %llu of %u\n",
                    n, (unsigned long long)nbad, np);
    }
    if (out)
        fclose(out);
    return done == nchunks ? 0 : 2;
}

/* ---------------------------------------------------------------- sweep */

int run_sweep(const char *dir, int n, int sym, int nchunks, int maxlen,
              int list, int gz)
{
    char path[4096];
    int N = n * (n - 1) / 2;
    if (maxlen < 0 || maxlen > N)
        maxlen = N;
    mkdir_p(dir);
    snprintf(path, sizeof path, "%s/chunks", dir);
    mkdir_p(path);
    if (!sym && list == LIST_REPS)
        list = LIST_ALL;
    check_config(dir, n, sym, nchunks, maxlen, list, gz);

    double t0 = now();
    tables_t T;
    tables_build(&T, n);
    fprintf(stderr, "S_%d: %u permutations, %u covers, largest level %u (%.1fs)\n",
            n, T.nperm, T.off[T.nperm], T.maxlevel, now() - t0);

    uint32_t nb = 0;
    uint32_t *bottoms = malloc(sizeof(uint32_t) * T.nperm);
    for (uint32_t u = 0; u < T.nperm; u++)
        if (!sym || (T.cw0[u] >= u && 2 * T.len[u] <= N))
            bottoms[nb++] = u;

    int *todo = malloc(sizeof(int) * (size_t)nchunks), ntodo = 0;
    for (int c = 0; c < nchunks; c++) {
        snprintf(path, sizeof path, "%s/chunks/%05d.stat", dir, c);
        if (!file_exists(path))
            todo[ntodo++] = c;
    }
    fprintf(stderr, "%u bottoms in %d chunks; %d chunks already done, %d to go; "
            "%d threads\n", nb, nchunks, nchunks - ntodo, ntodo,
            omp_get_max_threads());

    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    size_t nbytes = (T.nperm + 7) / 8;
    uint8_t *gbits = calloc(nbytes, 1);
    load_badw(dir, gbits, nbytes);

    int done = 0;
    double ts = now();
#pragma omp parallel
    {
        sweep_work_t W;
        sweep_work_init(&W, &T);
        cctx_t c;
        c.T = &T;
        c.sym = sym;
        c.list = list;
        c.buf = malloc(OUTBUF);
        c.badw = calloc(T.nperm, 1);
#pragma omp for schedule(dynamic, 1)
        for (int k = 0; k < ntodo; k++) {
            if (g_stop)
                continue;
            int chunk = todo[k];
            char tmp[4096], fin[4096];
            const char *ext = gz ? "txt.gz" : "txt";
            snprintf(tmp, sizeof tmp, "%s/chunks/%05d.%s.tmp", dir, chunk, ext);
            snprintf(fin, sizeof fin, "%s/chunks/%05d.%s", dir, chunk, ext);
            c.out = NULL;
            c.gz = NULL;
            if (gz) {
                c.gz = gzopen(tmp, "wb1");
                if (c.gz)
                    gzbuffer(c.gz, 1u << 18);
            } else {
                c.out = fopen(tmp, "w");
            }
            if (!c.out && !c.gz) {
                perror(tmp);
                exit(1);
            }
            c.blen = 0;
            memset(c.pairs, 0, sizeof c.pairs);
            memset(c.fails, 0, sizeof c.fails);
            memset(c.fails_id, 0, sizeof c.fails_id);
            memset(c.badw, 0, T.nperm);
            double tc = now();
            uint64_t pushes = 0;
            for (uint32_t b = (uint32_t)chunk; b < nb && !g_stop; b += (uint32_t)nchunks) {
                uint32_t u = bottoms[b];
                int top = sym ? N - 2 * T.len[u] : N - T.len[u];
                pushes += sweep_from(&T, &W, u, top < maxlen ? top : maxlen, on_level, &c);
            }
            if (!g_stop)
                flush_buf(&c);
            if (c.gz ? gzclose(c.gz) != Z_OK : fclose(c.out) != 0) {
                perror(tmp);
                exit(1);
            }
            if (g_stop) { /* abandon the partial chunk */
                unlink(tmp);
                continue;
            }
            commit_file(tmp, fin);
#pragma omp critical(badw)
            {
                for (uint32_t w = 0; w < T.nperm; w++)
                    gbits[w >> 3] |= (uint8_t)(c.badw[w] << (w & 7));
                save_badw(dir, gbits, nbytes);
            }
            write_stat(dir, chunk, &c, N, pushes, now() - tc);
#pragma omp critical
            {
                done++;
                double el = now() - ts;
                fprintf(stderr, "chunk %05d done  [%d/%d this run, %d/%d total]  "
                        "%.0fs elapsed, ETA %.0fs\n", chunk, done, ntodo,
                        nchunks - ntodo + done, nchunks, el,
                        el / done * (ntodo - done));
            }
        }
        free(c.buf);
        free(c.badw);
        sweep_work_free(&W);
    }
    free(gbits);
    free(todo);
    free(bottoms);
    tables_free(&T);
    if (g_stop) {
        fprintf(stderr, "interrupted; completed chunks are saved, rerun to resume\n");
        run_summary(dir);
        return 3;
    }
    return run_summary(dir);
}

/* ------------------------------------------------------------- bottom */

typedef struct {
    const tables_t *T;
    int quiet;
    uint64_t pairs[MAXL], fails[MAXL];
} bctx_t;

static void on_bottom_level(void *vctx, uint32_t u, int d, const uint32_t *node,
                            const uint8_t *F, const vec_t *H, uint32_t cnt)
{
    (void)H;
    bctx_t *c = vctx;
    const tables_t *T = c->T;
    char a[MAXN + 1], b[MAXN + 1];
    format_perm(PERM(T, u), T->n, a);
    c->pairs[d] += cnt;
    for (uint32_t s = 0; s < cnt; s++)
        if (!F[s]) {
            c->fails[d]++;
            if (!c->quiet) {
                format_perm(PERM(T, node[s]), T->n, b);
                printf("%s %s %d\n", a, b, d);
            }
        }
}

/* All w >= u in one sweep (e.g. u = id: the dual Schubert polynomials D_w). */
int run_bottom(const uint8_t *up, int n, int maxlen, int quiet)
{
    tables_t T;
    tables_build(&T, n);
    if (maxlen < 0 || maxlen > T.N)
        maxlen = T.N;
    bctx_t c;
    memset(&c, 0, sizeof c);
    c.T = &T;
    c.quiet = quiet;
    sweep_work_t W;
    sweep_work_init(&W, &T);
    uint32_t u = perm_rank(up, n);
    sweep_from(&T, &W, u, maxlen, on_bottom_level, &c);
    sweep_work_free(&W);
    char a[MAXN + 1];
    format_perm(up, n, a);
    uint64_t tp = 0, tf = 0;
    fprintf(stderr, "# bottom u = %s in S_%d: pairs (u, w) with w >= u\n", a, n);
    fprintf(stderr, "# %4s %12s %12s\n", "len", "pairs", "SCNP fails");
    for (int d = 0; d <= maxlen; d++)
        if (c.pairs[d]) {
            fprintf(stderr, "  %4d %12llu %12llu\n", d,
                    (unsigned long long)c.pairs[d], (unsigned long long)c.fails[d]);
            tp += c.pairs[d];
            tf += c.fails[d];
        }
    fprintf(stderr, "  %4s %12llu %12llu\n", "all", (unsigned long long)tp,
            (unsigned long long)tf);
    tables_free(&T);
    return 0;
}
